export const getLocalImage = (filename: string, gender?: 'boy' | 'girl' | null) => {
  // Fallbacks: 1. gender folder, 2. umum folder
  const prefix = gender === 'boy' ? 'pria' : (gender === 'girl' ? 'wanita' : 'umum');
  if (imageMap[`${prefix}_${filename}`]) return imageMap[`${prefix}_${filename}`];
  if (imageMap[`umum_${filename}`]) return imageMap[`umum_${filename}`];
  // If still not found, return undefined so caller can handle placeholder
  return undefined;
};
